mapper.select:
SELECT L.API_CALL_LOG_ID, L.EXTERNAL_API_ID, A.API_NAME, L.FIRE_INSTANCE_ID, L.HTTP_STATUS, L.STARTED_AT, L.FINISHED_AT, L.RUN_MILLIS, L.STATUS, L.ERROR_MESSAGE, L.CREATED_AT FROM SCHED_EXTERNAL_API_CALL_LOG L LEFT JOIN SCHED_EXTERNAL_API A ON L.EXTERNAL_API_ID = A.EXTERNAL_API_ID WHERE 1 = 1
AND A.API_NAME LIKE '%' || #{apiName} || '%'
AND L.STATUS = #{status}
AND L.STARTED_AT >= #{startDate}
AND L.STARTED_AT < #{endDateExclusive}
ORDER BY L.CREATED_AT DESC, L.API_CALL_LOG_ID DESC OFFSET #{offset} ROWS FETCH NEXT #{size} ROWS ONLY

SELECT COUNT(*)
FROM SCHED_EXTERNAL_API_CALL_LOG L
LEFT JOIN SCHED_EXTERNAL_API A
  ON L.EXTERNAL_API_ID = A.EXTERNAL_API_ID
WHERE 1 = 1

	AND A.API_NAME LIKE '%' || #{apiName} || '%'


	AND L.STATUS = #{status}


	AND L.STARTED_AT  >=  #{startDate}


	AND L.STARTED_AT  <  #{endDateExclusive}
